App.register({group:'workspace',label:'04 / 项目工作区',routes:[{path:'workspace/projects',title:'项目中心',icon:'▣',permission:'workspace',render(){const ps=App.accessibleProjects();return UI.page('WORKSPACE / PROJECTS','创作项目中心','项目是短剧生产的主业务对象，承载剧本版本、生产计划、镜头单元、资产与交付。',(DB.state.identity==='auditor'?'' : UI.btn('＋ 新建项目','project:new','btn-primary')),`<div class="grid grid-4">${UI.metric('全部项目',ps.length,'当前租户归属','▣')}${UI.metric('制作中',ps.filter(p=>p.status==='制作中').length,'AI 任务运行中','◌')}${UI.metric('待审核',ps.filter(p=>p.status.includes('审核')).length,'需要人工决策','!')}${UI.metric('已交付',ps.filter(p=>p.status==='已交付').length,'正式交付记录','↗')}</div><div class="card section-gap"><div class="toolbar"><div class="toolbar-left"><b class="small">项目列表</b><select class="field" style="width:auto" id="project-status"><option value="all">全部状态</option><option>制作中</option><option>已交付</option><option>异常待处理</option></select></div><input class="search" data-filter placeholder="搜索项目名称 / 编号"></div>${UI.table(['项目','题材','负责人','集数进度','当前阶段','状态','更新','操作'],ps.map(p=>`<tr data-search="${UI.esc(p.title)} ${UI.esc(p.id)}" data-project-row data-status="${UI.esc(p.status)}"><td><div class="entity"><div class="entity-mark">${UI.esc(p.title.slice(0,1))}</div><div><div class="entity-name">${UI.esc(p.title)}</div><div class="entity-meta mono">${UI.esc(p.id)}</div></div></div></td><td>${UI.esc(p.genre)}</td><td>${UI.esc(p.owner)}</td><td><div style="width:90px">${UI.progress(Math.round((p.done||0)/Math.max(p.episodes||1,1)*100),(p.done||0)+'/'+p.episodes+' 集')}</div></td><td>${UI.esc(p.stage)}</td><td>${UI.tag(p.status,p.status==='已交付'?'green':p.status.includes('异常')?'red':p.status.includes('审核')?'orange':'blue')}</td><td class="muted">${UI.esc(p.updated)}</td><td><button class="btn btn-sm" data-action="project:open" data-id="${UI.esc(p.id)}">档案</button></td></tr>`))}</div>`); }},{path:'workspace/detail',title:'项目档案',icon:'◧',permission:'workspace',render(){const p=App.project();if(!p)return UI.page('WORKSPACE / PROJECT FILE','尚未选择项目','选择当前身份有权访问的项目，查看项目主档与追溯关系。','',`<div class="card">${UI.empty('没有可用项目','创建项目或切换到已授权的租户空间。')}</div>`);const tenant=DB.tenants.find(t=>t.id===p.tenant),projectAssets=DB.assets.filter(a=>a.tenant===p.tenant&&a.project===p.title),visualCount=projectAssets.filter(a=>a.type==='人物设定'||a.type==='场景设定').length,audioCount=projectAssets.filter(a=>a.type==='音频').length;return UI.page('WORKSPACE / PROJECT FILE','项目档案 · '+UI.esc(p.title),'统一查看当前项目主档、剧本版本、生产计划、数字资产和最终交付。',UI.btn('进入 AI 创作','go:studio/brief','btn-lime'),`<div class="grid grid-3"><div class="card"><div class="eyebrow">PROJECT ID</div><div class="mono" style="font-size:17px;margin:9px 0">${UI.esc(p.id)}</div>${UI.tag(p.status,p.status==='已交付'?'green':'blue')}</div>${UI.metric('计划集数',p.episodes,'当前已完成 '+(p.done||0)+' 集','▤')}${UI.metric('累计生产成本','¥'+(p.cost||0).toLocaleString(),'关联当前项目的生产任务','￥')}</div><div class="grid grid-2 section-gap"><div class="card"><div class="card-title">生产链路</div><div class="timeline section-gap">${['创意策划与剧本','人工剧本审核','导演分镜与视觉设计','视频镜头生产','音频与后期合成','AI 质检与人工终审','正式交付与归档'].map((s,i)=>`<div class="timeline-item"><i class="timeline-dot ${i<(p.status==='已交付'?7:p.status==='制作中'?4:p.scriptApproved?3:1)?'done':''}"></i><div><div class="timeline-title">${s}</div><div class="timeline-meta">${i===1?'人工审核节点':i===5?'人工最终审核节点':'AI 自动生产 / 系统记录'}</div></div></div>`).join('')}</div></div><div class="card"><div class="card-title">项目追溯关系</div><div class="kpi-line"><span>剧本版本</span><b>V${p.scriptVersion||1}</b></div><div class="kpi-line"><span>镜头生产单元</span><b>${p.shotCount||p.episodes*8}</b></div><div class="kpi-line"><span>视觉 / 音频资产</span><b>${visualCount} / ${audioCount}</b></div><div class="kpi-line"><span>质检综合分</span><b>${p.quality||'待检测'}/100</b></div><div class="kpi-line"><span>归属租户</span><b>${UI.esc(tenant?.name||'未知租户')}</b></div>${UI.btn('查看数字资产','go:assets/library','btn-sm')}</div></div>`);}}]});